"""Formatting helpers for values exposed by the MiniJinja CLI."""
import json
import math
from decimal import Decimal


def _plain(value):
    if value is None:
        return None
    if isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, dict):
        return {str(k): _plain(v) for k, v in value.items()}
    if isinstance(value, (tuple, list, range)):
        return [_plain(v) for v in value]
    return str(value)


def display(value):
    """MiniJinja's human readable value representation (used in expressions)."""
    if value is None:
        return "none"
    if value is True:
        return "true"
    if value is False:
        return "false"
    if isinstance(value, str):
        return value
    if isinstance(value, float):
        if math.isnan(value):
            return "NaN"
        if math.isinf(value):
            return "inf" if value > 0 else "-inf"
        # MiniJinja's display format uses a plain decimal representation,
        # including for values where Python switches to exponent notation.
        result = format(Decimal(repr(value)), "f")
        return result if "." in result else result + ".0"
    if isinstance(value, dict):
        def key_repr(key):
            if isinstance(key, str):
                return json.dumps(key, ensure_ascii=False)
            return display(key)
        return "{" + ", ".join(key_repr(k) + ": " + display(v) for k, v in value.items()) + "}"
    if isinstance(value, (list, tuple, range)):
        return "[" + ", ".join(display(v) if not isinstance(v, str) else json.dumps(v, ensure_ascii=False) for v in value) + "]"
    return str(value)


def json_output(value, pretty=False):
    """Serialize a template value as JSON, mapping none to JSON null."""
    return json.dumps(_plain(value), ensure_ascii=False, indent=2 if pretty else None,
                      separators=None if pretty else (",", ":"), allow_nan=False)


def status_code(value):
    """Return the observed --expr-out=status process status code."""
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, int):
        return value & 255
    if isinstance(value, float) and value.is_integer():
        return int(value) & 255
    # For nonnumeric values the CLI's convention is inverted from normal truthiness.
    return 1 if not value else 0
