"""A small formatter for MiniJinja's public token dump mode."""
import json
import re


def dump_tokens(template, syntax=None):
    syntax = syntax or {}
    bs = syntax.get("block-start", "{%")
    be = syntax.get("block-end", "%}")
    vs = syntax.get("variable-start", "{{")
    ve = syntax.get("variable-end", "}}")
    cs = syntax.get("comment-start", "{#")
    ce = syntax.get("comment-end", "#}")
    out = []
    pos = 0
    tag_re = re.compile("|".join(re.escape(x) for x in (vs, bs, cs) if x))
    while pos < len(template):
        m = tag_re.search(template, pos)
        if not m:
            out.append("TemplateData(" + json.dumps(template[pos:], ensure_ascii=False) + ")")
            break
        if m.start() > pos:
            out.append("TemplateData(" + json.dumps(template[pos:m.start()], ensure_ascii=False) + ")")
        opener = m.group()
        closer = ve if opener == vs else be if opener == bs else ce
        body_start = m.end()
        # A '-' adjacent to delimiters is a whitespace control marker, not a token.
        if body_start < len(template) and template[body_start] == '-':
            body_start += 1
        end = template.find(closer, body_start)
        if end < 0:
            out.append("TemplateData(" + json.dumps(template[m.start():], ensure_ascii=False) + ")")
            break
        body_end = end - 1 if end > body_start and template[end - 1] == '-' else end
        body = template[body_start:body_end]
        if opener == cs:
            pos = end + len(closer)
            if pos < len(template) and template[pos] == '-':
                pos += 1
            continue
        is_var = opener == vs
        out.append("VariableStart" if is_var else "BlockStart")
        out.extend(_lex(body))
        out.append("VariableEnd" if is_var else "BlockEnd")
        pos = end + len(closer)
        if pos < len(template) and template[pos] == '-':
            pos += 1
    if not template:
        return ""
    return "\n".join(out) + "\n"


_TOKEN = re.compile(r'''\s+|(?:0[xX][0-9a-fA-F]+|\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)|(?:"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*')|[A-Za-z_][A-Za-z_0-9]*|==|!=|>=|<=|//|\*\*|\+|-|\*|/|%|>|<|=|\||\.|,|:|\(|\)|\[|\]|\{|\}|~''')
