class StrictUndefined(Exception): pass
def render(t,ctx,opts):
    # MiniJinja removes one source trailing newline before rendering; the CLI
    # adds its own final newline unless --no-newline is set.
    if t.endswith('\n'):
        t=t[:-1]
    vs,ve=opts.get('variable-start','{{'),opts.get('variable-end','}}')
    cs,ce=opts.get('comment-start','{#'),opts.get('comment-end','#}')
    t=re.sub(re.escape(cs)+'.*?'+re.escape(ce),'',t,flags=re.S)
    def replace(m):
        expr=m.group(1).strip()
        if opts.get('strict'):
            path=re.fullmatch(r'[A-Za-z_][\w]*(?:\.[A-Za-z_][\w]*)*',expr)
            if path:
                cur=ctx
                for part in expr.split('.'):
                    if not isinstance(cur,dict) or part not in cur: raise StrictUndefined(expr)
                    cur=cur[part]
        return esc(expression(expr,ctx),opts)
    t=re.sub(re.escape(vs)+r'([\s\S]*?)'+re.escape(ve),replace,t)
    return t

