    """Return the CLI's automatic escaping mode for a template filename."""
    ext = os.path.splitext(filename or "")[1].lower()
    if ext in (".html", ".htm", ".xml"):
        return "html"
    if ext in (".json", ".yaml", ".yml"):
        return "json"
    return "none"


