        cmd = line.strip()
        if cmd in (".quit", ".exit"):
            break
        if cmd == ".help":
            sys.stdout.write(_HELP)
        elif cmd.startswith(".set "):
            arg = cmd[5:]
            if "=" not in arg:
                sys.stdout.write("error: invalid command\n")
            else:
                key, expr = arg.split("=", 1)
                key = key.strip()
                if not key:
                    sys.stdout.write("error: invalid command\n")
                else:
                    try:
                        context[key] = evaluate(expr, context)
                    except Exception as exc:
                        sys.stdout.write("error: " + str(exc) + "\n")
        elif cmd.startswith(".unset "):
            key = cmd[7:].strip()
            if not key:
                sys.stdout.write("error: invalid command\n")
            else:
                context.pop(key, None)
        elif cmd.startswith(".render "):
            try:
                sys.stdout.write(str(render(cmd[8:], context)) + "\n")
            except Exception as exc:
                sys.stdout.write("error: " + str(exc) + "\n")
        elif cmd:
            try:
                value = evaluate(cmd, context)
                # The REPL uses a debug representation, so top-level strings retain quotes.
                if isinstance(value, str):
                    result = json.dumps(value, ensure_ascii=False)
                elif value is None:
                    result = "none" if cmd.strip() in ("none", "null") else ""
                else:
                    from valuefmt import display
                    result = display(value)
                sys.stdout.write(result + "\n")
            except Exception as exc:
                sys.stdout.write("error: " + str(exc) + "\n")
    return 0

